package com.vandorlabs.neoforge.screen;
import com.vandorlabs.redstone.ChannelList;
import com.vandorlabs.screen.ScreenFamily;
import com.vandorlabs.neoforge.redstone.NativeRedstoneChannels;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.*;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.block.Blocks;
/** Replays the released implementation's live range/local edits without replacing row authority. */
final class ScreenTransmissionActionsChecks {
 static void run(ServerLevel world,java.util.Map<ScreenFamily,NativeScreenBlock> blocks)throws Exception{
 var path=java.nio.file.Path.of(System.getProperty("screenTransmissionActionsReference"));var cases=com.google.gson.JsonParser.parseString(java.nio.file.Files.readString(path)).getAsJsonObject().getAsJsonArray("cases");if(!com.google.gson.JsonParser.parseString(java.nio.file.Files.readString(path)).getAsJsonObject().get("sha256").getAsString().equals("1ed5909db77f5af4f037d08caa29afdb1c345ae586105fca934c7c4308fe2d8a"))throw new AssertionError("Transmission Source corpus changed");int index=0;BlockPos pos=new BlockPos(4700,90,4700);world.getChunkAt(pos);
 for(var block:blocks.values()){
  clock(world,100);world.setBlock(pos,block.defaultBlockState(),2);var tile=(NativeScreenEntity)world.getBlockEntity(pos);var root=tile.saveWithoutMetadata(world.registryAccess());var first=cases.get(index).getAsJsonObject();var original=TagParser.parseTag(first.get("controls").getAsString());root.put("RedstonePrimary",original);tile.loadWithComponents(root,world.registryAccess());NativeRedstoneChannels.flush(world);var service=tile.controlService();sample(world,pos,tile,cases.get(index++).getAsJsonObject());
  world.setBlock(pos.east().below(),Blocks.STONE.defaultBlockState(),2);world.setBlock(pos.east(2).below(),Blocks.STONE.defaultBlockState(),2);world.setBlock(pos.east(),Blocks.STONE.defaultBlockState(),2);world.setBlock(pos.east(2),Blocks.REDSTONE_WIRE.defaultBlockState(),2);tile.applyTransmission(new NativeScreenTransmissionEdit(ChannelList.of(74104),256,true));if(world.getBlockState(pos.east(2)).getValue(net.minecraft.world.level.block.RedStoneWireBlock.POWER)!=15)throw new AssertionError("Local output failed strong-conductor second-hop notification");sample(world,pos,tile,cases.get(index++).getAsJsonObject());clock(world,105);tile.applyTransmission(new NativeScreenTransmissionEdit(ChannelList.EMPTY,4,true));sample(world,pos,tile,cases.get(index++).getAsJsonObject());clock(world,110);tile.applyTransmission(new NativeScreenTransmissionEdit(ChannelList.EMPTY,16,false));sample(world,pos,tile,cases.get(index++).getAsJsonObject());clock(world,121);service.expire(121);sample(world,pos,tile,cases.get(index++).getAsJsonObject());var saved=tile.saveWithoutMetadata(world.registryAccess());service.stop();sample(world,pos,tile,cases.get(index++).getAsJsonObject());tile.loadWithComponents(saved,world.registryAccess());service.finishLoading();sample(world,pos,tile,cases.get(index++).getAsJsonObject());service.stop();for(int x=0;x<=2;x++)for(int y=-1;y<=0;y++)world.setBlock(pos.offset(x,y,0),Blocks.AIR.defaultBlockState(),2);
 }System.out.println("Native Screen transmission actions PASS snapshots="+index);
 }
 private static void clock(ServerLevel world,long now){((net.minecraft.world.level.storage.ServerLevelData)world.getLevelData()).setGameTime(now);}
 private static void sample(ServerLevel world,BlockPos pos,NativeScreenEntity tile,com.google.gson.JsonObject expected)throws Exception{CompoundTag actual=new CompoundTag();tile.controls(0).write(actual);if(!actual.equals(TagParser.parseTag(expected.get("controls").getAsString())))throw new AssertionError("Transmission row mismatch phase="+expected.get("phase")+" expected="+expected.get("controls")+" actual="+actual);if(tile.transmission().range()!=expected.get("range").getAsInt()||tile.transmission().local()!=expected.get("local").getAsBoolean()||tile.localOutput()!=expected.get("weak").getAsInt())throw new AssertionError("Transmission options/local phase="+expected.get("phase"));int i=0;for(int channel:new int[]{73161,73162,73163,74104}){if(NativeRedstoneChannels.level(world,pos,channel)!=expected.getAsJsonArray("near").get(i).getAsInt()||NativeRedstoneChannels.level(world,pos.east(8),channel)!=expected.getAsJsonArray("far").get(i).getAsInt())throw new AssertionError("Transmission channel phase="+expected.get("phase")+" channel="+channel);i++;}}
}
